#!/usr/bin/env node

const fetch = require('node-fetch');
const argv = require('./argv');
const SwaggerParser = require('swagger-parser');
const fs = require('fs');

const {options} = argv;

if (argv.targets.indexOf('generate') !== -1) {
  fetch(options.source)
    .then(res => res.text())
    .then(data => {
      fs.writeFileSync('data.yaml', data);
      SwaggerParser.validate(`${process.cwd()}/data.yaml`, function(err, api) {
        if (err) {
          console.error(err);
        }
        else {
          console.log(api);
        }
        process.exit();
      });
      // fs.unlinkSync('.data');
    }).catch(error => {
      console.log(error);
      process.exit();
    });
}
else {
  argv.argv.help();
}

